/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// The <t>PurchTable</t> table extension
/// </summary>
[ExtensionOf(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity))]
final class METPurchPurchaseOrderConfirmationLineEntity_Extension
{
}

Method.Source:
    /// <summary>
    /// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        MetItemSiteSettingsSetup    metItemSiteSettingsSetup;
        InventItemBarcode           inventItemBarcode;

        changecompany(this.DataAreaId)
        {
            select firstonly TempRcvLimit from metItemSiteSettingsSetup
                where metItemSiteSettingsSetup.ItemId == this.ItemNumber 
                && metItemSiteSettingsSetup.InventSiteId == this.ReceivingSiteId;

            this.METPOLineTempRcvLimit = metItemSiteSettingsSetup.TempRcvLimit? metItemSiteSettingsSetup.TempRcvLimit: InventTable::find(this.ItemNumber).PdsBestBefore;

            this.METPOLineInventoryUOM = InventTableModule::find(this.ItemNumber,ModuleInventPurchSales::Invent).UnitId;

            purchLine metpurchLine;

            select firstonly RecId, CurrencyCode from metpurchLine
                        index hint PurchLineIdx
                        where metpurchLine.PurchId         == this.PurchaseOrderNumber
                           && metpurchLine.LineNumber      == this.LineNumber
                           && !metpurchLine.IsDeleted;
            if(metpurchLine.RecId)
            {
                this.METPOlineTaxAmount = Tax::calcTaxAmount(this.SalesTaxGroupCode, this.SalesTaxItemGroupCode,
                                            DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), 
                                            metpurchLine.CurrencyCode, this.LineAmount, TaxModuleType::Purch);
            }

            //get the default barcode
            select firstonly ItemBarCode from inventItemBarcode
                where inventItemBarcode.itemId == this.ItemNumber
                   && inventItemBarcode.UnitID == this.PurchaseUnitSymbol
                   && inventItemBarcode.METDefault == NoYes::Yes;

            this.METPOLineConfPurchGTIN = inventItemBarcode.itemBarCode;
        }
        next postload();
    }
